using namespace DT::PAR;
using namespace std;

inline std::complex<double>
operator+(int lhs, const std::complex<double>& rhs)
{
    return std::complex<double>(static_cast<double>(lhs), 0.0) + rhs;
}
   template <typename T>
std::complex<T> operator*(int lhs, const std::complex<T>& rhs) {
   return static_cast<T>(lhs) * rhs;
}

inline double Csc(double x) {
return 1.0 / sin(x);
}

inline double Sec(double x) {
return 1.0 / cos(x);
}

inline double Cot(double x) {
return std::tan(M_PI_2 - x);
}

std::complex<double> DT::A1A1TAtaTree(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);

    return -((sqrt(2.)*(MHSqcomp - MS1Sqcomp)*s*token15*token2*token33*(token11 + token9)*(s - 4.* (MTA*MTA)))/((MHSqcomp - s)*(-MS1Sqcomp + s)*token28));
}

std::complex<double> DT::A1A1TAtaTreeConj(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);

    return std::conj(-((sqrt(2.)*(MHSqcomp - MS1Sqcomp)*s*token15*token2*token33*(token11 + token9))/(2.*(MHSqcomp - s)*(-MS1Sqcomp + s)*token28)));
}

