    double Delta  = s*(s - 4.0*m2);        // = s*(-4*m2 + s)
    double lambda = std::sqrt(Delta);


    double x = (4.0*m2*s) / ((s + lambda)*(s + lambda));
    double z = (4.0*m2*m2) / ((s - 2.0*m2 + lambda)*(s - 2.0*m2 + lambda));

    std::complex<double> MH1 = sqrt(MH*MH - std::complex<double>(0,MH*WH));
